using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container resolves HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city by name.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. \"Seattle\"")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var current = doc.RootElement.GetProperty("current_condition")[0];
        var tempC = current.GetProperty("temp_C").GetString();
        var desc = current.GetProperty("weatherDesc")[0].GetProperty("value").GetString();
        var humidity = current.GetProperty("humidity").GetString();

        return $"Weather in {city}: {desc}, {tempC}°C, humidity {humidity}%";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var forecasts = doc.RootElement.GetProperty("weather");
        var lines = new List<string> { $"Forecast for {city}:" };

        for (int i = 0; i < days && i < forecasts.GetArrayLength(); i++)
        {
            var day = forecasts[i];
            var date = day.GetProperty("date").GetString();
            var maxC = day.GetProperty("maxtempC").GetString();
            var minC = day.GetProperty("mintempC").GetString();
            lines.Add($"  {date}: {minC}°C – {maxC}°C");
        }

        return string.Join("\n", lines);
    }
}

